<script setup lang="ts">
import {computed,ref} from 'vue'
import {api} from '../api'
import {usePolling} from '../usePolling'
import {number,price,percent,time,money} from '../format'
import {tracks,poolFresh,poolOrder} from '../opportunities'
import type {PoolSnapshot,PoolRow} from '../opportunities'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
const data=ref<PoolSnapshot|null>(null),now=ref(Date.now()),track=ref('Early'),query=ref(''),selected=ref<string|null>(null)
const history=ref<PoolSnapshot[]>([])
const study=ref<{symbols:number;hours:number;completeWindows:number;closedHour10xWindows:number;positiveSymbols:string[];cohorts:{label:string;compressed12PercentFraction:number|null}[]}|null>(null)
const stateFor=(r:PoolRow)=>track.value==='Early'?(r.tenfold?.status??'十倍研究待刷新'):r.state
const supports=(r:PoolRow)=>track.value==='Early'?(r.tenfold?.supporting??[]):r.supporting
const risks=(r:PoolRow)=>track.value==='Early'?(r.tenfold?.risks??[]):r.risks
const missing=(r:PoolRow)=>track.value==='Early'?(r.tenfold?.missing??['十倍研究证据待刷新']):r.missing
const {error}=usePolling(async signal=>{const [s,h,t]=await Promise.all([api<PoolSnapshot>('/api/opportunities',{signal}),api<PoolSnapshot[]>('/api/opportunities/history?limit=6',{signal}),api<typeof study.value>('/api/research/tenfold',{signal})]);data.value=s;history.value=h;study.value=t;now.value=Date.now()},15000)
const rows=computed(()=>data.value?.rows.filter(r=>r.tracks.includes(track.value)&&r.symbol.includes(query.value.trim().toUpperCase())).sort(poolOrder)??[])
const candidates=computed(()=>rows.value.filter(r=>(track.value==='Early'?r.tenfold?.status==='十倍假设待验证':r.state==='结构候选')&&poolFresh(data.value!,r,now.value)))
const detail=computed(()=>data.value?.rows.find(r=>r.symbol===selected.value))
const coverage=computed(()=>Object.entries(data.value?.universe.reduce<Record<string,number>>((acc,r)=>{acc[r.status]=(acc[r.status]??0)+1;return acc},{})??{}))
const universe=computed(()=>data.value?.universe.filter(r=>r.symbol.includes(query.value.trim().toUpperCase())).slice(0,30)??[])
</script>
<template><PageIntro eyebrow="MARKET OPPORTUNITIES · TWO TRACKS" title="妖币埋伏与排行机会" description="全市场粗筛，提前埋伏与涨幅机会分别观察。链上身份未核验不会阻断交易所量价分析。"><RouterLink class="replay-action" to="/">查看模拟账户 →</RouterLink></PageIntro>
<p v-if="error" class="radar-notice" role="alert">{{error}}</p>
<template v-if="data">
<div class="stats"><StatCard label="全市场扫描" :value="data.universe.length" foot="逐个记录可用、失鲜和流动性不足"/><StatCard label="本轮深度池" :value="`${data.rows.length} / ${data.deepLimit}`" foot="提前观察、涨幅、走弱及轮换分配"/><StatCard :label="track==='Early'?'十倍研究待验证假设':'本组结构候选'" :value="candidates.length" :foot="track==='Early'?'不等于预测成功率，不直接触发旧A策略':'量价结构与OI范围符合，仍需风控与新报价'"/><StatCard label="本组待补数据" :value="rows.filter(r=>track==='Early'?stateFor(r)!=='十倍假设待验证':r.state==='待补数据').length" foot="不足不算未触发，也不算安全"/></div>
<p class="radar-notice">这些是研究观察对象，不是保证上涨或立即买入的推荐。每分钟读取全市场报价并更新池子，约每5分钟留档；模拟只在新小时采集窗口生成执行信号。<RouterLink to="/network">流量与连接 →</RouterLink></p>
<section class="detail pool-controls"><div class="pool-tabs"><button v-for="(label,key) in tracks" :key="key" class="text-button" :aria-pressed="track===key" @click="track=key;selected=null">{{label}} · {{data.rows.filter(r=>r.tracks.includes(key)).length}}</button></div><label class="search"><input v-model="query" aria-label="搜索机会合约" placeholder="搜索合约，例如 TRB"></label>
<p v-if="track==='Early'">研究目标是起点后30日内价格达到10倍，不是杠杆收益。BTC、ETH与锚定资产不进入此组；流通市值不超过3亿美元先作为待验证研究范围。未核验市值只用于安排核验优先级，不能认定为小市值。筹码集中度及其变化、钱包归属、解锁与价格阶段分开核对。</p><p v-else-if="track==='Momentum'">观察涨幅≥3%的标的，区分首次突破、回踩和过热；消息催化未知就保留未知。</p><p v-else-if="track==='Weakness'">观察跌幅≥3%的合约。下跌本身不是空单依据，需有压力失效点和OI等证据。</p><p v-else>剩余名额每5分钟轮换，给未进入主要池子的合约补齐数据。入选不代表已有买卖信号。</p>
<p>{{candidates.length?'优先复核表中假设的支持、风险与缺失条件，不能据此认定将涨十倍。':'本组暂未形成可重点复核的假设；下列对象仍需继续取证。'}} 快照 {{time(data.asOf)}} · {{data.version}}</p></section>
<div class="market-panel table-scroll"><table><thead><tr><th>合约 / 判断</th><th>价格 / 24h涨跌</th><th>{{track==='Early'?'流通市值 / 核验状态':'72h区间 / 小时量比'}}</th><th>{{track==='Early'?'筹码集中 / 24h变化':'OI数量24h / 数据'}}</th><th>主要依据与风险</th><th>核对</th></tr></thead><tbody><tr v-for="r in rows" :key="r.symbol"><td><strong>{{r.symbol}}</strong><small>{{poolFresh(data,r,now)?stateFor(r):'报价失鲜，等待更新'}}</small></td><td>{{price(r.price)}}<small>{{percent(r.return24h)}} · {{money(r.volume24h)}}</small></td><td v-if="track==='Early'">{{money(r.tenfold?.marketCapUsd)}}<small>{{r.tenfold?.verifiedSmallCap?'已核验小市值':'待核验，不算通过'}}</small><small v-if="r.tenfold?.referenceMarketCapUsd!=null&&!r.tenfold.verifiedSmallCap">未核验参考 {{money(r.tenfold.referenceMarketCapUsd)}}</small></td><td v-else>{{percent(r.range72hPercent)}}<small>{{number(r.hourVolumeRatio)}} 倍</small></td><td v-if="track==='Early'">{{percent(r.tenfold?.adjustedTop10Percent)}}<small>{{number(r.tenfold?.top10Change24hPoints)}} 个百分点</small></td><td v-else>{{percent(r.oi24hPercent)}}<small>小时线 {{r.hours}} / 337</small></td><td>{{supports(r)[0]??'支持证据待补'}}<small>{{risks(r)[0]??missing(r)[0]??'逐项核对完整证据'}}</small></td><td><button class="text-button" @click="selected=r.symbol">分析详情</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="empty">本组暂无匹配对象；不强制凑出推荐。</td></tr></tbody></table></div>
<section v-if="detail" class="detail"><div class="section-heading"><h2>{{detail.symbol}} · 支持、反对与未知</h2><button class="text-button" @click="selected=null">收起</button></div><h3>支持</h3><p v-for="line in supports(detail)" :key="line">{{line}}</p><h3>风险 / 反证</h3><p v-for="line in risks(detail)" :key="line">{{line}}</p><p v-if="!risks(detail).length">尚未观测到上述风险项不代表安全，仍须检查缺失信息。</p><h3>缺失</h3><p v-for="line in missing(detail)" :key="line">{{line}}</p><template v-if="track==='Early'&&detail.tenfold"><h3>30日十倍研究预测</h3><p>{{detail.tenfold.prediction}}。概率：{{percent(detail.tenfold.probability30d10x)}}。</p><p>十倍目标情景价 {{price(detail.tenfold.targetPrice10x)}}；流通供给不变时对应市值 {{money(detail.tenfold.impliedMarketCap10x)}}，不是所需资金流入量，也不是价格预测值。</p><p>过去30日价格倍数 {{number(detail.tenfold.past30DayPriceMultiple)}}；持币地址数 {{number(detail.tenfold.holderCount,0)}}，24h变化 {{percent(detail.tenfold.holderChange24hPercent)}}。</p><p>市值源 {{time(detail.tenfold.marketCapSourceTime)}}；集中度源 {{time(detail.tenfold.concentrationSourceTime)}}。该月度研究不会直接转成旧A横盘策略的模拟委托。</p></template><h3 v-if="track!=='Early'">当前参考结构计划</h3><p v-for="plan in (track==='Early'?[]:detail.plans)" :key="plan.id">{{plan.direction==='Short'?'空头':'多头'}} / {{plan.strategy}} · 参考 {{price(plan.plan?.referenceEntry)}} · 失效止损 {{price(plan.plan?.stop)}} · 两级目标 {{price(plan.plan?.target1)}} / {{price(plan.plan?.target2)}}<small>{{plan.plan?.target1Basis}} / {{plan.plan?.target2Basis}}；仅供观察，不是模拟意向或成交。</small></p><p v-if="track!=='Early'&&!detail.plans.length">尚无合格结构计划，不人为编造止损和目标。</p><p>价格源 {{time(detail.priceSourceTime)}}，收到 {{time(detail.priceReceivedTime)}}；OI源 {{time(detail.oiSourceTime)}}，收到 {{time(detail.oiReceivedTime)}}。</p><RouterLink :to="{path:'/mappings',query:{symbol:detail.symbol}}">核对资产身份 →</RouterLink> · <RouterLink to="/watchtower">加入个人观察列表 →</RouterLink></section>
<details class="detail"><summary>其余合约为何没进入本轮深度池</summary><p v-for="[status,count] in coverage" :key="status">{{status}}：{{count}}</p><p>粗筛可用但本轮没有名额的合约会参与后续轮换；没有经过深度分析的不标成策略淘汰。用上方搜索框查询，最多展示30个。</p><div class="table-scroll"><table><thead><tr><th>合约</th><th>24h涨跌</th><th>粗筛状态</th><th>本轮深度池</th></tr></thead><tbody><tr v-for="r in universe" :key="r.symbol"><td>{{r.symbol}}</td><td>{{percent(r.return24h)}}</td><td>{{r.status}}</td><td>{{data.rows.some(d=>d.symbol===r.symbol)?'已进入':'未进入 / 等待轮换'}}</td></tr></tbody></table></div></details>
<section v-if="study" class="detail"><h2>历史30日十倍诊断</h2><p>{{study.symbols}} 个事后选取合约、{{number(study.hours,0)}} 根小时线；{{study.completeWindows}} 个完整30日窗口中，{{study.closedHour10xWindows}} 个窗口曾出现小时收盘价达到起点10倍，涉及 {{study.positiveSymbols.join('、')}}。</p><p>十倍窗口中仅 {{percent((study.cohorts.find(c=>c.label==='10x close')?.compressed12PercentFraction??0)*100)}} 满足原72小时振幅≤12%，因此该条件不再作为十倍研究的硬门槛。样本有重叠和事后选择偏差，这不是预测成功率；最高价触及、收盘达到和月末维持十倍分别统计，不能认定每天连续上涨。</p></section><details class="detail"><summary>最近留档与研究入口</summary><p v-for="h in history" :key="h.id">{{time(h.asOf)}} · {{h.rows.length}} 个深度对象 · {{h.version}}</p><p>原始快照含名单、支持、反证、缺失、数据源时间、参数指纹和参考计划，保留90天供复盘。</p><RouterLink to="/strategy-research">两套策略与历史案例 →</RouterLink> · <RouterLink to="/template-library">历史样板 →</RouterLink> · <RouterLink to="/speculative-evidence">市值与链上专项证据 →</RouterLink></details>
</template><p v-else-if="!error" class="radar-notice">正在等待首次全市场观察快照。</p></template>
<style scoped>.pool-tabs{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:18px}.pool-tabs button{padding:10px;border:1px solid #2d4149;border-radius:6px}.pool-tabs button[aria-pressed=true]{background:#173c34;border-color:#62d5b0;color:#a3f5de}.pool-controls .search{max-width:360px}small{display:block;max-width:34em;overflow-wrap:anywhere}summary{cursor:pointer;font-weight:600}td{vertical-align:top}</style>
